-- UniChat classroom seed SQL
-- Bu dosya backend/tools/generate_classroom_seed_sql.py ile üretilir.
BEGIN;
DELETE FROM campus_spaces WHERE source_file = 'Derslikler.xlsx';
DELETE FROM classrooms WHERE source_file = 'Derslikler.xlsx';

ON CONFLICT (normalized_building_name) DO UPDATE SET
    building_name = EXCLUDED.building_name,
    aliases = EXCLUDED.aliases,
    normalized_aliases = EXCLUDED.normalized_aliases,
    source_file = EXCLUDED.source_file,
    updated_at = NOW();

;

;

COMMIT;
